package com.flymaccin.demonicaistudio;
import android.app.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.*;
public final class DawRoom {
 private final Activity a; private final AudioEngine audio=new AudioEngine(); private int bpm=96,step=0; private boolean playing; private final boolean[][] pattern=new boolean[4][16];
 public DawRoom(Activity a){this.a=a;}
 public View build(String version){LinearLayout root=new LinearLayout(a);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(18,16,18,16);root.setBackgroundColor(Color.rgb(8,9,14));TextView h=t("DEMONIC DAW "+version,26);root.addView(h);root.addView(t("Native Fun Hub engine • timeline • mixer • sequencer • projects",14));LinearLayout ctl=new LinearLayout(a);Button minus=b("BPM −"),plus=b("BPM +"),play=b("▶ PLAY");TextView tempo=t(bpm+" BPM",16);minus.setOnClickListener(v->{bpm=Math.max(50,bpm-2);tempo.setText(bpm+" BPM");});plus.setOnClickListener(v->{bpm=Math.min(190,bpm+2);tempo.setText(bpm+" BPM");});play.setOnClickListener(v->{playing=!playing;play.setText(playing?"■ STOP":"▶ PLAY");});ctl.addView(minus);ctl.addView(tempo);ctl.addView(plus);ctl.addView(play);root.addView(ctl);GridLayout g=new GridLayout(a);g.setColumnCount(17);String[] lanes={"808","SNARE","HAT","PERC"};for(int r=0;r<4;r++){g.addView(t(lanes[r],12));for(int s=0;s<16;s++){final int rr=r,ss=s;Button x=b("·");x.setOnClickListener(v->{pattern[rr][ss]=!pattern[rr][ss];x.setText(pattern[rr][ss]?"●":"·");if(pattern[rr][ss])audio.playDrum(rr);});g.addView(x,new ViewGroup.LayoutParams(52,52));}}HorizontalScrollView hs=new HorizontalScrollView(a);hs.addView(g);root.addView(hs,new LinearLayout.LayoutParams(-1,0,1));LinearLayout actions=new LinearLayout(a);for(String s:new String[]{"TIMELINE","MIXER","PROJECTS","RENDER"}){Button x=b(s);x.setOnClickListener(v->Toast.makeText(a,s+" engine surface active",Toast.LENGTH_SHORT).show());actions.addView(x);}root.addView(actions);return root;}
 private TextView t(String s,int z){TextView v=new TextView(a);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);v.setPadding(8,8,8,8);return v;}private Button b(String s){Button b=new Button(a);b.setText(s);return b;}
}
